ontent\": \"Exchange Stabilization Fund\", \"description\": null, \"id\": 16, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [198, 1468, 1382, 1519], \"page_id\": 9}], \"content\": \"International financial statistics 84\", \"description\": null, \"id\": 17, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [187, 1545, 1371, 1596], \"page_id\": 9}], \"content\": \"Capital movements 89\", \"description\": null, \"id\": 18, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [198, 1608, 1367, 1668], \"page_id\": 9}], \"content\": \"Corporations and other business-type activities 126\", \"description\": null, \"id\": 19, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [194, 1690, 1376, 1741], \"page_id\": 9}], \"content\": \"Cumulative table of contents 127\", \"description\": null, \"id\": 20, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [194, 1806, 1063, 1849], \"page_id\": 9}], \"content\": \"Note: Details of figures may not add to totals because of rounding.\", \"description\": null, \"id\": 21, \"type\": \"footnote\"}, {\"bbox\": [{\"coord\": [71, 29, 96, 55], \"page_id\": 10}], \"content\": \"II\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [1323, 12, 1588, 58], \"page_id\": 10}], \"content\": \"Treasury Bulletin\", \"description\": null, \"id\": 1, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [604, 293, 1080, 324], \"page_id\": 10}], \"content\": \"Treasury Financing Operations\", \"description\": null, \"id\": 2, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [62, 406, 279, 430], \"page_id\": 10}], \"content\": \"October Refunding\", \"description\": null, \"id\": 3, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [62, 454, 809, 632], \"page_id\": 10}], \"content\": \"On September 17 the Treasury announced an exchange offering of 8% Treasury Notes of Series E-1971, dated October 1, 1969, due May 15, 1971, at par, 7-3/4% Treasury Notes of Series A-1973, dated October 1, 1969, due May 15, 1973, at par, and 7-1/2% Tr